    acc += choose_general_cutoff(seed, seed + 3);
    acc += count_exp_digits(seed, seed + 3);
    acc += normalize_sig_exp(seed, seed + 3);
    acc += trim_trailing_zeros(seed, seed + 3);
    acc += apply_fixed_prec(seed, seed + 3);
    acc += apply_exp_prec(seed, seed + 3);
    acc += hexfloat_nibble_span(seed, seed + 3);
    acc += round_even_digit(seed, seed + 3);
    acc += carry_through_nines(seed, seed + 3);
    acc += insert_decimal_slot(seed, seed + 3);
    acc += leading_zero_frac(seed, seed + 3);
    acc += upper_exp_letter(seed, seed + 3);
    acc += signed_zero_policy(seed, seed + 3);
    acc += inf_nan_token_span(seed, seed + 3);
    acc += showpoint_policy(seed, seed + 3);
    acc += locale_decimal_span(seed, seed + 3);
    acc += scientific_guard(seed, seed + 3);
